/// A registered byte-only command dispatcher. The host awaits its replies off
/// foreground and applies completed replies on GPUI foreground. Dispatchers
/// generated by [`ModuleDefinition`] execute commands on their owned Tokio runtime.
pub trait NativeModule: Send + Sync {
    fn module_id(&self) -> [u8; 16];
    fn module_digest(&self) -> [u8; 32];
    /// Execute a short UI operation on GPUI foreground. `None` selects the
    /// asynchronous worker path. UI handlers must not perform blocking I/O.
    fn invoke_foreground(
        &self,
        _function_id: u32,
        _args: &[u8],
        _window: &mut gpui::Window,
        _cx: &mut gpui::App,
    ) -> Option<Result<Vec<u8>, String>> {
        None
    }
    /// Blocking convenience for tests and worker threads; never call from GPUI
    /// foreground. Generated dispatchers reject calls from within Tokio.
    fn invoke(&self, function_id: u32, args: &[u8]) -> Result<Vec<u8>, String>;
    /// Generated dispatchers abort the Tokio task when this future is dropped.
    /// Custom dispatchers must supply their own execution/cancellation policy.
    fn invoke_async(
        &self,
        function_id: u32,
        args: Vec<u8>,
    ) -> futures::future::BoxFuture<'_, Result<Vec<u8>, String>> {
        Box::pin(async move { self.invoke(function_id, &args) })
    }
}

